//! `tot completions <shell>` and `tot man` feed release tarballs, packages, and
//! the Nix build. The output is generated by clap so it cannot drift from the
//! real CLI.

use std::process::Command;

#[test]
fn clap_generates_completions_and_a_man_page() {
    let exe = env!("CARGO_BIN_EXE_tot");

    let bash = Command::new(exe)
        .args(["completions", "bash"])
        .output()
        .unwrap();
    assert!(bash.status.success());
    assert!(String::from_utf8_lossy(&bash.stdout).contains("_tot"));

    for shell in ["zsh", "fish"] {
        let output = Command::new(exe)
            .args(["completions", shell])
            .output()
            .unwrap();
        assert!(output.status.success(), "{shell} completions failed");
        assert!(
            !String::from_utf8_lossy(&output.stdout).trim().is_empty(),
            "{shell} completions were empty"
        );
    }

    let man = Command::new(exe).arg("man").output().unwrap();
    assert!(man.status.success());
    let page = String::from_utf8_lossy(&man.stdout);
    assert!(
        page.contains(".TH tot 1"),
        "man page did not contain a roff title"
    );
    assert!(
        page.contains("agent harness for coding"),
        "man page has no description"
    );
}
